local config = {
  str_season_maze_s3_title = "꿈의 잔향",
  str_season_maze_s3_subtitle = "꿈의 잔향",
  str_season_maze_s3_even_desc_1001 = "당신은 멍하니 주변의 모습을 바라보았다... 적도, 보물도... 아무것도 없었다. 「쿵!」 소리와 함께, 보이지 않는 공기의 벽이 앞으로 나아가려는 당신을 제자리에 굳게 막아섰다.\n\n「상황 분석 중... 해당 영역은 에너지 파동이 매우 활발해 정확하게 위치를 파악할 수 없습니다.」 계몽자의 얼굴은 고속 연산으로 인해 빨갛고 뜨겁게 변했다. 「이곳은 미지의 영역입니다. 프랜시스 교수님은 이런 꿈의 영역이 주는 불확실성을 좋아한다고 하셨습니다. 게다가 이곳에는 가끔씩 꿈의 주인이 남긴 그림자도 비치곤 합니다.」\n\n그 말은 여기서 당신의 친구를 만날 수 있을지도 모른다는 뜻 같았다.\n\n「이탈 경로 3종을 분석했습니다. 선택해 주세요. 참고로 경로마다 다른 보상이 주어집니다. 최악의 가정을 해 두시기 바랍니다. 그렇지 않으면 게임 경험에 영향을 줄 수 있습니다.」\n\n당신의 의문을 간파한 듯, 계몽자는 이어서 말했다. 「최악의 가정은 보상이 없는 경우를 말합니다.」 당신은 생각했다. 결과가 나빠봤자 그 정도라면 선택은 쉬울 것이라고 말이다... 아마도.",
  str_season_maze_s3_even_desc_1002 = "「상황 분석 중...」 계몽자는 마치 수많은 영롱한 보물들이 바람에 흘러가고 있다는 듯이 주위의 공기를 진지하게 응시하고 있었다. 비록 당신에게는 아무것도 보이지 않았지만, 적어도 이곳이 새로운 미지의 영역이라는 것만은 알 수 있었다.\n\n「이탈 경로 3종을 분석했습니다. 선택해 주세요.」\n\n마치 당신을 격려하려는 듯, 계몽자는 당신의 옷자락을 끌어당기며 목소리를 낮추었다. 「귀띔해 드리겠습니다. 계몽자는 아버지가 이번에 꿈의 금화를 얻을 수 있을 것 같다는 예감이 듭니다.」",
  str_season_maze_s3_even_desc_1003 = "「상황 분석 중...」 그동안 미지의 영역에서 「불확실성」으로 인해 자극적인 느낌을 경험했기 때문인지, 당신은 계몽자가 어떤 계산 결과를 내놓을지 기대되기 시작했다.\n\n「정보 결합, 아버지도 프랜시스 교수님처럼 미지의 영역을 좋아하게 되었군요.」\n\n계몽자는 이 결과에 무척 만족하는 듯했다. 「설명, 이제 아버지는 알게 되었을 것입니다. 계몽자는 아버지를 속이지 않았습니다. 꿈의 세계 속 게임은 무척 재미있습니다. 아닙니다, 계몽자가 받는 느낌은 없습니다. 그러나 계몽자는 드림 워커의 느낌을 짐작할 수 있습니다.」",
  str_season_maze_s3_even_desc_1004 = "계몽자는 바닥에 쪼그려 앉아 모래 한 움큼을 쥐어 들었다.\n\n「설명, 프랜시스 교수님에게 들은 적이 있습니다. 바닷속에는 부드러운 마음씨를 가진 한 생물이 있는데, 자신의 고통이 담긴 눈물을 체내의 모래에 스며들게 해서 한층 한층 감싸고, 그렇게 그 생물의 고통은 아름다운 진주로 변한다고 합니다.」\n\n계몽자는 잠시 멈추었고, 이 순간 그녀는 마치 동화 듣기를 좋아하는 평범한 소녀처럼 보였다. 「사실 꿈의 세계에서도 비슷한 물건이 있답니다.」",
  str_season_maze_s3_even_desc_1005 = "「정보 결합 중, 악몽은 좋은 꿈과 다릅니다.」\n\n그것은 물론 다른 것이었고, 당신에게는 생각할 필요조차 없이 단정할 수 있는 사실이었다. 그러나 계몽자는 수많은 정보를 수집해야만 이러한 결론을 도출할 수 있었다.\n\n「오직 악몽 속에서만 꿈의 주인의 고통이 판타즘 스톤으로 만들어집니다.」 그제서야 당신은 계몽자가 무엇을 생각했는지 깨달았다.\n\n이윽고 당신은 계몽자가 꿈의 의미를 알고 있는지, 그녀가 자신의 꿈을 가질 수 있는지 궁금해지기 시작했다.",
  str_season_maze_s3_even_desc_1006 = "「희, 흰돌고래 씨!」 화려한 왕관을 쓴 소녀가 큰 소리로 외치면서 치맛자락을 붙잡고 달려왔다.\n\n그녀는 아직 꿈의 진상을 알아채지 못한 것 같았고, 그저 그녀의 기괴한 수확을 즐겁게 자랑할 뿐이었다. 「저... 로빈의 조언을 듣고 근처에 산호 몇 개를 심어 봤는데요. 이제 전부 수확했어요! 엄청난 보물을 만들었더라고요~」\n\n「혹시 이중에... 마, 마음에 드는 거 있으세요? 선물로 드릴게요...」",
  str_season_maze_s3_even_desc_1007 = "\"「최근 마을의 지하통로가 진흙으로 막혔다는 민원이 많이 들어오고 있어요...」\n\n자칭 바다의 여왕인 소녀는 풀이 죽어 고개를 숙인 채 말했다. 「저도 실수로 진흙을 밟아서 크게 넘어졌거든요... 정말 창피해요...」\n\n당신은 소녀를 위로했고, 진흙을 퍼내 마을 주변의 방어에 사용할 것을 제안했다. 그 말을 들은 소녀의 눈이 반짝였다. 「그, 그럼 그렇게 할게요!」\"",
  str_season_maze_s3_even_desc_1008 = "「전 디나, 로빈이랑 같이 또 항아리 속의 여인을 만나러 갔어요... 문제를 해결하는 방법을 배우려고요.」\n\n「그 사람은 가르쳐 줄 수 있다고 했어요... 하지만...」 여전히 여왕의 신분에 적응하지 못한 소녀는 망설이며 자신의 당혹감을 당신에게 전했다.\n\n「전... 강력한 보물과 오래된 이야기 중에서 선택을 해야만 해요... 당신이라면 뭘 선택할 건가요?」",
  str_season_maze_s3_even_desc_1009 = "「코놀리! 왜 또 흰돌고래랑 놀고 있어?!」 「마법 연습할 시간이야, 코놀리!」 「코놀리는 좋은 여왕, 좋은 계약자가 되겠다고 약속했어!」\n\n검고 자그마한 세 마리의 신비한 생물이 쫓아와 눈앞의 소녀에게 마법 수련을 하라고 아우성쳤다.\n\n어쩔 줄 모르는 소녀의 모습을 보며, 당신은 그들과 함께 마법 수련을 하기로 결정했다.",
  str_season_maze_s3_even_desc_1010 = "멀리서 익숙한 목소리가 들려왔다. 가만히 들어보니 왠지 여동생을 아끼는 어느 황새치가 대원들을 소집하고 있는 듯했다.\n\n「디나예요! 갑자기 집결이라니... 무슨 위험한 일이라도 생긴 걸까요?」 코놀리는 순찰에 참여하는 주민들을 걱정하는 듯했다.\n\n「저, 저도 도우러 가야 할까요? 사람을 더 구하는 게 좋을까요... 아니면 제가 직접 참가하는 게 좋을까요...」",
  str_season_maze_s3_even_desc_1011 = "당신은 코놀리와 함께 마법을 수행하면서, 갑자기 튀어나온 어인들도 처리하며, 해저 마을의 방어도 강화하느라 계몽자와의 약속도 잊어버릴 정도로 바쁘게 움직였다.\n\n그녀가 당신을 붙잡고 땅에 있는 조개껍데기를 가리킬 때가 되어서야 당신은 정신을 차렸고, 그 안에 있는 것은 당신에게 필요한 하얀 구슬이었다.\n\n「어라, 그 아이는...」 코놀리도 당신 곁에 있는 계몽자에게 주목했다. 「그 아이도 흰돌고래 씨의 동족인가요...?」",
  str_season_maze_s3_even_desc_1012 = "당신은 동족 겸 후견인으로서 계몽자를 코놀리에게 소개했고, 그녀를 희망을 지키기 위해 만들어진 아이라고 말해 주었다.\n\n「훌쩍... 정말 착한 아이구나... 혼자 그렇게 오랫동안 살았다니...」\n\n코놀리는 눈앞의 「작은 흰돌고래」 꼭 껴안아 주었다. 「진주 갖고 싶니? 내가 잔뜩 줄게!」",
  str_season_maze_s3_even_desc_1013 = "「윙」하는 소리와 함께 갑자기 머리가 조여오는 것이 느껴졌고, 눈앞의 계몽자는 갑자기 다섯, 여섯, 일곱, 여덟, 아홉... 개의 분신이 생긴 것 같았다...\n\n「상황 분석 중...」 당신은 계몽자의 얼굴이 잘 보이지 않았다. 그러나 착각인지는 몰라도 계몽자의 목소리가 평소보다 더 긴장해서 떨리는 것 같았다. 「경고, 드림 워커는 꿈의 세계에서 충분한 턴 수를 유지해야 합니다. 그래야만 꿈의 세계에서의 안정적인 활동을 보장할 수 있습니다.」\n\n당신이 정신을 차리자, 계몽자는 그제서야 눈 가리고 아웅 하듯이 해명했다. 「알림, 드림 워커의 안정은 계몽자의 안정에도 영향을 줄 수 있습니다. 계몽자가 고장 나지 않도록 드림 워커는 꿈의 세계 속 턴 관리에 주의해야 합니다.」",
  str_season_maze_s3_even_desc_1014 = "「확인, 프랜시스 교수님이 왜 꿈의 세계 보조 모듈을 개발하셨는지 궁금하신 건가요?」\n\n당신이 고개를 끄덕이자, 계몽자는 무척 열심히 기억을 떠올리는 듯 두 눈을 감았다... 아마 그녀는 지금 천만 년간 저장된 정보를 검색하고 있을지도 모른다.\n\n「답변, 추방된 아이테르들은 일종의 히스테리에 시달렸습니다. 이를 치료하기 위해 드림 워커였던 프랜시스 교수는 환자의 꿈으로 들어갔습니다. 드림 워커가 꿈의 세계에서 행동하는 것은 목숨이 걸린 위험한 일이며, 따라서 꿈의 세계 속 에너지 파동을 정확히 조사하고 모니터링할 수 있는 보조 도구가 반드시 필요합니다.」\n\n「이러한 이유로 프랜시스 교수님은 계몽자를 위해 꿈의 세계 보조 모듈을 개발하셨습니다.」",
  str_season_maze_s3_even_desc_1015 = "「답변, 프랜시스 교수님은 과학 연구만이 아이테르를 구할 수 있다고 믿으셨습니다. 그러나 한편으로는 세상에 관측과 연구가 불가능한 신비로운 힘이 존재한다고 믿으셨습니다...」\n\n「...아닙니다, 아버지가 이해하는 신학이 아닙니다. 신비로운 힘이 신비로운 이유는 현재의 과학 기술로는 이를 관측하고 연구할 수 없기 때문입니다.」\n\n프랜시스 교수에 대한 이야기가 나오자, 당신은 계몽자가 프랜시스 교수에 대한 「괴로운 정크 파일」을 삭제했던 것을 떠올리지 않을 수 없었다.\n\n계몽자는 갑자기 무언가를 민감하게 눈치챈 듯 말했다. 「상황 분석 중... 계몽자가 정크 파일을 유지하기를 아버지가 원한다면, 음성 명령으로 관련 설정을 진행할 수 있습니다.」\n\n깜짝 놀란 당신은 설마 계몽자가 「감응 모듈」 같은 것을 설치한 것은 아닐까 생각했다.",
  str_season_maze_s3_even_desc_1016 = "계몽자는 입술을 살짝 열었다가 얼른 닫았다. 그녀는 뭔가 물어보고 싶은 듯했지만, 명령 입력이 없어 대화를 먼저 시작할 수 없었다.\n\n당신의 동의를 받은 그녀는 마침내 입을 열었다. 「질문, 계몽자는 알고 싶습니다. 외부 세계도 이 꿈의 세계처럼 똑같이 생겼습니까?」\n\n생각해 보니 계몽자는 한 번도 그녀가 「태어난」 탑을 떠난 적이 없었다. 당신은 그녀에게 바깥세상은 훨씬 더 넓다고 말했고, 또한 나중에 그녀를 데리고 산과 바다... 세계 곳곳을 들러봐 주겠다고 약속했다.\n\n「알림, 그때까지 부디 아버지가 자신의 능력 향상에 전념해 주시길 바랍니다.」 비록 계몽자는 무표정한 얼굴로 당신에게 주의를 주었지만, 그녀 뒤의 작은 큐브 속 폭죽이 터지는 이미지는 이미 그녀의 심정을 폭로하고 있었다.\n\n사실 당신은 진작부터 계몽자가 그저 평범한 기계가 아니라고 느끼고 있었다.",
  str_season_maze_s3_even_desc_1017 = "당신은 계몽자가 그동안 어떤 꿈의 세계들에 가 보았는지 궁금했다.\n\n「정보 검색 중...」 계몽자는 눈을 감았다가 다시 번쩍 뜨고 말했다. 「죄송합니다. 아버지는 아직 관련 정보를 개방할 권한이 없습니다.」 하지만 당신에게 권한이 없다면, 지금 이 세상에 권한을 가진 사람이 누가 있을까.\n\n「저의 제조자인 프랜시스 교수님이 설정하신 규칙입니다. 프랜시스 교수님은 꿈의 세계에서 활동하며 충분한 경험치를 얻어야만, 강한 심장과 비범한 지혜를 단련해서 고대 아이테르의 복잡한 꿈의 세계를 견뎌낼 수 있다고 하셨습니다.」\n\n계몽자는 손바닥을 당신의 어깨에 얹었다. 「정보 결합 중... 계몽자는 언젠가 아버지가 권한을 획득할 수 있을 거라고 믿습니다.」",
  str_season_maze_s3_even_desc_1018 = "「정보 검색 중...」 당신의 질문에 계몽자는 늘 모든 답을 주려고 노력했지만, 이번 검색 시간은 그 어느 때보다도 길었다.\n\n「죄송합니다. 계몽자의 데이터베이스에는 계몽자의 에너지원에 대한 자료가 저장되어 있지 않습니다. 하지만 안심하세요, 계몽자의 가동 이력을 토대로 추측한다면, 적어도 아버지가 살아 있는 동안에는 계몽자가 에너지원 문제로 인해 다운될 일은 없을 것입니다.」\n\n...어처구니없는 대답을 들은 당신은 안심해야 할지, 말아야 할지 알 수 없었다.",
  str_season_maze_s3_even_desc_1019 = "당신은 예전에 이미 와 보았던 이 꿈의 세계에 아이테르 스타일로 보이는 도구와 공간이 새로 생겼다는 것을 깨달았다.\n\n「답변, 꿈의 세계에서는 구역에 따라 다른 에너지 파동을 보입니다. 드림 워커들이 쉽게 활동할 수 있도록, 계몽자는 동일한 에너지 파동을 가진 구역에 표식을 생성합니다. 계몽자의 데이터베이스에는 아이테르 스타일의 설비 모형만 있기 때문에, 아이테르 스타일의 물품으로 에너지 파동을 형상화할 수밖에 없습니다.」\n\n계몽자는 잠시 멈추었다가 마치 무슨 잘못이라도 한 것처럼 조심스럽게 물었다. 「질문, 다른 양식으로 바꿔드릴까요?」\n\n하지만 당신은 이대로가 좋을 것 같았다.\n\n이렇게 하면 적어도 꿈속에서라도 진짜 「집」을 가진 느낌이 들었기 때문이다.",
  str_season_maze_s3_even_desc_1020 = "귀환의 탑에서 보았던 앵무조개가 갑자기 생각난 당신은 돌아서서 계몽자에게 물었다.\n\n계몽자는 눈을 감았다. 「정보 검색 중...」\n\n그러나 이번에는 금방 눈을 뜨고 당신을 바라보았다. 「아버지의 설명으로 보았을 때, 말씀하시는 물건은 노틸러스입니다. 일반적으로 아이테르는 한 개 또는 여러 개의 노틸러스를 가지고 있습니다. 노틸러스의 수는 아이테르가 지닌 재산에는 영향을 미치지 않지만, 희귀한 외관의 노틸러스는 그 자체의 가치를 넘어 일종의 수집품이 될 정도로 각광받았습니다. 하지만 계몽자는 아버지에게 제안합니다. 투자는 신중해야 합니다.」\n\n비록 지금의 노틸러스는 한때 아이테르 사회에서 가졌던 실용적 가치를 잃은 지 오래지만, 계몽자의 말은 왠지 지금 시대에도 그대로 적용되고 있는 듯하다.",
  str_season_maze_s3_even_desc_1021 = "계몽자는 현재 대륙에서 유통되고 있는 화폐가 나이티움이라는 말을 들었지만, 계몽자 주변의 큐브들은 놀라거나 하는 반응이 없었다.\n\n설마 계몽자는 이 사실을 이미 예상한 것일까.\n\n「답변, 계몽자는 통화란 사회가 일정한 단계로 발전하며 탄생하는 필연적인 산물이라는 것을 알고 있습니다. 그러나 계몽자에게 있어 화폐는 가치를 지니지 않습니다.」\n\n그렇다면 계몽자에게는 대체 무엇이 가치가 있는 것일까.\n\n계몽자의 얼굴이 다시 붉어지고 뜨거워지기 시작했다. 그것은 그저 「두뇌」가 빠르게 가동하고 있기 때문이라는 것을 당신은 알고 있었다. 「답변, 계몽자는 이 질문에 대한 답을 찾지 못했습니다. 그러나 계몽자는 과거의 정보를 바탕으로 아버지의 동행과 칭찬이 계몽자에게 가장 가치 있는 화폐라고 추측합니다.」",
  str_season_maze_s3_even_desc_1022 = "당신은 꿈의 세계에서 이곳을 탐색하는 데 도움이 되는 물건들을 주워 본 적이 있었다. 그러나 그 물건들은 이 세계에 원래 존재했을 물건 같지 않았다.\n\n「답변, 꿈의 에너지 흐름은 이 세계에만 국한되지 않습니다. 비록 원리는 알려지지 않았지만, 연구에 따르면 모든 꿈의 세계의 에너지는 모종의 규칙에 따라 서로 교환되고 있습니다. 그 물건들은 꿈의 에너지 흐름에 따라 서로 다른 꿈의 세계로 떠밀려 온 것이며, 어떤 꿈의 세계에도 속하지 않기 때문에 그것들을 가지고 갈 수 있는 것입니다.」\n\n그것들은 대체 어디서 온 것들일까.\n\n당신이 갈피를 잡지 못하자 계몽자는 이어서 대답했다. 「그것들은 모두 과거의 드림 워커들이 잃어버린 보물들입니다.」",
  str_season_maze_s3_even_desc_1023 = "꿈의 세계에 들어온 지 이미 오랜 시간이 지났다. 대체 이곳의 여정은 언제 끝나는 것일까.\n\n계몽자는 당신의 피로를 감지했다. 「잠깐 쉬어도 됩니다. 꿈의 에너지 균형을 회복하는 것은 하루아침에 이루어지는 일이 아닙니다. 일반적으로 꿈의 세계에는 종종 여러 개의 단계가 존재합니다. 꿈의 주인이 현실에서 자신을 더 깊게 가둬버릴수록, 꿈의 단계도 늘어납니다. 하지만 꿈의 에너지가 균형을 되찾으면 현실에서도 더 뚜렷하게 호전됩니다.」\n\n계몽자는 조금 더 가까이 다가왔다. 「서술, 아버지가 피곤하시다면 계몽자는 언제든지 아버지에게 따뜻한 음료를 준비해 드릴 수 있습니다.」",
  str_season_maze_s3_even_desc_1024 = "꿈의 세계를 깊이 탐색해 나가면서, 당신은 점점 더 꿈의 세계 속 규칙에 적응하고 있는 자신을 발견하게 되었다.\n\n「알림, 꿈의 세계 속 규칙에 따라, 아버지는 알고 있는 오로리안을 떠올려서 그들을 불러내고 아버지를 돕게 할 수 있습니다. 그러나 그들은 결코 오로리안 본인이 아니라는 점을 잊지 마세요. 그리고 꿈속이기 때문에 뭐든지 마음대로 할 수 있다고도 생각하지 마세요. 비록 계몽자의 도움이 있다고 해도, 꿈의 세계 속에 존재할 수도 있는 위험을 무시해서는 안 됩니다.」\n\n당신은 계몽자가 말하는 속도가 달라진 것에 신경이 쓰였다. 「이상의 내용은 꿈의 세계 보조 모듈이 일정 단계가 개방되면 필수적으로 진행되는 안내이며, 아버지에 대한 계몽자의 판단을 의미하지 않습니다.」",
  str_season_maze_s3_even_desc_1025 = "당신은 계몽자가 당신을 등진 채로 그녀 옆에 있는 큐브에 어떤 수치를 기록하고 있는 것을 발견했다...\n\n「경고, 가까이 오지 마세요!」\n\n누군가 자신에게 다가오는 것을 느낀 계몽자는 갑자기 볼륨을 높여 경고했지만, 다가온 사람이 당신임을 확인한 계몽자의 볼륨은 다시 정상으로 돌아왔다. 「서술, 안심하세요. 계몽자는 꿈의 세계 속 아버지의 행동을 공정하고 객관적으로 평가해서, 그에 상응하는 드림 포인트를 기록할 것입니다.」\n\n당신은 그제서야 계몽자가 자신의 일거수일투족을 관찰하면서 점수까지 매기고 있었다는 사실을 깨달았다.\n\n「설명, 본 작업은 계몽자가 제공하는 추가 보조 기능입니다. 이를 통해 아버지의 꿈의 세계 속 행동 능력을 더 잘 모니터링할 수 있습니다. 만약 일정한 기준을 충족한다면, 계몽자는 아버지에게 추가 보상을 제공할 것입니다.」\n\n역시 계몽자를 얕봐서는 안 될 일이다. 그녀는 철두철미한 훈련의 대가다.",
  str_season_maze_s3_even_desc_1026 = "계몽자의 안내를 받은 당신은 텅 빈 것처럼 보이는 공기 속에서 왠지 수많은 「별」들이 반짝이며 바람에 떠돌고 있는 것을 발견했다.\n\n「서술, 그것은 꿈의 세계의 에너지를 구성하는 최소 입자입니다. 꿈의 금화는 꿈의 세계의 규칙을 통해 아버지가 원하는 다른 물건으로 변화할 수 있습니다...」\n\n당신이 의구심을 품자 계몽자는 말을 바꾸어 설명했다. 「꿈의 금화는 쉽게 말해서 꿈의 세계 속 통용 화폐입니다. 단, 꿈의 금화는 많이 모을수록 좋지만, 계몽자는 과도한 축재를 권장하지 않습니다.」",
  str_season_maze_s3_even_desc_1027 = "「서술, 꿈의 세계를 떠도는 꿈을 먹는 그림자는 끊임없이 꿈을 갉아먹고, 그 폐허 위에 둥지를 짓습니다. 그 둥지를 깨끗이 제거해야만 꿈의 에너지가 다시 균형을 되찾을 수 있습니다.」\n\n계몽자는 언제나 당신을 위해 꿈의 세계의 규칙을 반복해서 설명해 주었다.\n\n「계몽자는 아버지에게 제안합니다. 꿈의 세계에서 충분한 꿈의 금화를 누적한 후, 둥지의 가장 깊은 곳에 있는 악몽의 독기에 도전해 보시기 바랍니다.」",
  str_season_maze_s3_even_desc_1028 = "「으아아... 쫓아오지 마세요! 전 나라 다스리는 일 같은 건 모르고... 계약자 자격도 없어요...」\n\n당신은 성으로 돌아오기로 했던 코놀리가 돌아오지 않은 채, 길가에 혼자 앉아서 울고 있는 것을 발견했다.\n\n그러나 당신이 무슨 말을 하기도 전에, 코놀리 뒤에서 세 명의 작은 사역마가 나타났다. 「그렇게 말하지 마. 넌 아직 우리도 있고, 황새치도 있고, 가오리랑 흰돌고래 씨도 있잖아! 기운 내!」",
  str_season_maze_s3_even_desc_1029 = "코놀리는 자신이 여전히 떠나간 가족, 나쁜 친척, 그리고 나약한 자신에 대해 생각하고 있다고 인정했다. 그리고 세상에는 강한 사람들이 정말 많은데, 오히려 자신이 이 자리에 떠밀려 앉게 되고, 이상한 힘을 얻게 된 것을 마음에 두고 있었다.\n\n「사실... 마을의 위기가 해결되고 나면... 전 퇴위하는 편이 좋지 않을까요...」 그녀는 작은 소리로 중얼거렸다.\n\n당신은 그녀에게 그런 생각이 들 때면 레스토랑에 가서 마음껏 먹거나, 좋아하는 음악을 연주해 보라고 제안했다. 때로는 현재의 행복이 과거의 고통조차 덮어버릴 수 있기 때문이다.",
  str_season_maze_s3_even_desc_1030 = "계몽자는 코놀리의 옷에 관심이 많았고, 왠지 그 옷의 동화 같은 느낌이 어디서 나오는 것인지 알고 싶어 하는 듯했다. 게다가 그녀에게 유리구두 한 켤레도 주고 싶어 했다.\n\n「으읏... 그런 신발을 신으면... 넘어질지도 몰라요...」\n\n그래서 일행은 더 움직이기 편한 물건을 찾았다. 「유리구두는 정말 예쁘지만... 그래도 전 지금 모습을 더 많이 생각해 왔어요.」 코놀리는 부끄러워하며 당신을 향해 미소를 지으며 말했다.",
  str_season_maze_s3_help_tab_1 = "꿈의 잔향",
  str_season_maze_s3_help_tab_2 = "드림 포인트",
